<?php use App\Core\View;ob_start(); ?><h1>Gestão de usuários</h1><div class="card"><h2>Criar acesso excepcional</h2><form method="post" action="/admin/usuarios"><input type="hidden" name="_csrf" value="<?=$csrf?>"><label>Nome<input name="name" required></label><label>E-mail<input name="email" type="email" required></label><label>Senha temporária<input name="password" type="password" minlength="8" required></label><button class="btn">Criar e liberar sem cobrança</button></form></div><table><tr><th>Usuário</th><th>Plano</th><th>Status</th><th>Ações</th></tr><?php foreach($users as $u): ?><tr><td><?=View::e($u['full_name'])?><br><small><?=View::e($u['email'])?></small></td><td><?=View::e($u['plan']??'-')?></td><td><?=View::e($u['status'])?> · <?=$u['access_blocked_at']?'Bloqueado':'Liberado'?></td><td><form method="post" action="/admin/status"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><input type="hidden" name="status" value="<?=$u['status']==='active'?'suspended':'active'?>"><button><?=$u['status']==='active'?'Inativar':'Ativar'?></button></form><form method="post" action="/admin/<?= $u['access_blocked_at']?'desbloquear':'bloquear'?>"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><?php if(!$u['access_blocked_at']): ?><input name="reason" value="Bloqueio administrativo"><?php endif ?><button><?=$u['access_blocked_at']?'Desbloquear':'Bloquear'?></button></form><form method="post" action="/admin/liberar-acesso"><input type="hidden" name="_csrf" value="<?=$csrf?>"><input type="hidden" name="user_id" value="<?=$u['id']?>"><button>Liberar sem cobrança</button></form></td></tr><?php endforeach ?></table><?php $body=ob_get_clean();$title='Gestão de usuários';require __DIR__.'/layout.php'; ?>
